---编队类型列表处理
function FightTeamPresetDialog:OnTeamTypeListGetItemHandler(gridView, index)
    if index < 0 then
        return
    end
    local cell = gridView:NewListViewItem("ToggleCellNode1")
    local position = index + 1
    local scr = CfUtils.GetLuaScr(cell, FightTeamPresetTeamTypeCellPath)
    if isNotNull(scr) then
        scr:RefreshCell(
            TeamTypeConfig[position].name,
            position == self:GetTeamTypeIndex(), 
            position, 
            Bind(self, self.TeamTypeCellOnClickHandler)
        )
    end
    return cell
end

---编队类型cell点击回调
function FightTeamPresetDialog:TeamTypeCellOnClickHandler(index)
    if index == self:GetTeamTypeIndex() then return end
    
    self:SetTeamTypeIndex(index)
    local cell = self.TabListView:GetShownItemByItemIndex(#TeamTypeConfig - index)
    if isNotNull(cell) then
        local scr = CfUtils.GetLuaScr(cell, FightTeamPresetTeamTypeCellPath)
        scr:PlaySwitchAnimation()
    end
    self:RefreshUI()
    self.TabToggleUp:MovePanelToItemIndex(self:GetSelectedTeamIndex() - 1)
end

---编队列表处理
function FightTeamPresetDialog:OnTeamListGetItemHandler(listView, index)
    if index < 0 then return end

    local cell = listView:NewListViewItem("Cell")
    local position = index + 1
    local teamType = self:GetSelectedTeamType()
    local data = checkTable(TeamComponent:GetTeamInfoByTeamType(teamType)[position])
    local scr = CfUtils.GetLuaScr(cell, FightTeamPresetTeamCellPath)
    if isNotNull(scr) then
        scr:RefreshCell(
                data.name or TeamComponent:GetEmptyTeamName(position),
                position == self:GetSelectedTeamIndex(),
                position,
                Bind(self, self.TeamCellOnClickHandler)
        )
    end
    return cell
end

---编队cell点击回调
function FightTeamPresetDialog:TeamCellOnClickHandler(index)
    local teamType = self:GetSelectedTeamType()
    if index == self:GetSelectedTeamIndex() then
        UIModule.OpenDialog({id = Constants.UITypeIds.FightTeamNamePopup})
        return 
    end
    
    TeamComponent:SetSelectedTeamIndexByTeamType(index, teamType)
    self:RefreshUI()
end

---刷新编队成员事件处理
function FightTeamPresetDialog:RefreshTeamMemberEventHandler(body)
    if not self.isBack then
        local team = TeamComponent:GetSelectedTeamInfoByTeamType(self:GetSelectedTeamType()).cardsInfo
        self:RefreshTeamMembers(team, isNotNull(body) and body.skipAnim or nil)
        self:RefreshFightPower()
    end
end

---修改编队名称事件处理
function FightTeamPresetDialog:ModifyNameEventHandler(name)
    TeamComponent:SetTeamNameByTeamType(self:GetSelectedTeamType(), name, self:GetSelectedTeamIndex())
    self:RefreshUI()
end

function FightTeamPresetDialog:BtnBackOnClickHandler()
