---刷新队伍成员
function FightTeamPresetDialog:RefreshTeamMembers(teams, isDontShowAni)
    self.teamTab = clone(teams)

    self._allTeamPosInfoGo = {}
    self._power = 0
    local teamType = self:GetSelectedTeamType()
    local teamIndex = self:GetSelectedTeamIndex()
    local count = teamType
    
    --- 计算战力需要星级 这里设置下
    ---@type TeamCatBallDojo[]
    local teamCats
    if self._isUnlockCatBall then
        teamCats = TeamComponent:GetTeamCatByTeamType(teamType, teamIndex)
        for index, value in ipairs(teamCats) do
            if checkNumber(value.playerCatId) > 0 then
                ---@type CatEggDojo
                local catEggDojo = CatEggComponent:GetCatById(value.playerCatId)
                value:SetStar(catEggDojo.star)
            end
        end
    end
    
    local nodes = self.TeamNodePar:GetChildren()
    for _, v in pairs(nodes) do
        CfUtils.SetActive(v, false)
    end
    
    -- 计算共鸣的情绪 id列表
    local emotionBonusDict = CardUtils.CalculateEmotionBonusDict(teams)

    for i = 1, count do
        local teamGo = self["TeamNode"..i]
        CfUtils.SetActive(teamGo, true)
        local showEmotionBonus = CardUtils.ConsumeEmotionBonusDict(teams[i], emotionBonusDict)
        self:RefreshTeamMember(teamGo, teams[i], i, teamCats, isDontShowAni, showEmotionBonus)
    end
    --
    for i = 1, count do
        local teamGo = self["TeamNode"..i]

        local scr = CfUtils.GetLuaScr(teamGo, UIFightTeamTeamNode)
        if scr then
            scr:InitChangePosInfo(self._allTeamPosInfoGo, function()
                -- local teamTab = TeamComponent:GetTeamInfoByTeamType(teamType, TeamComponent:GetSelectedTeamIndexByTeamType(teamType)).cardsInfo
                -- self:RefreshTeamMembers(teamTab, 1)
            end, nil, teamIndex)
        end
    end
end

--刷新队伍队员
function FightTeamPresetDialog:RefreshTeamMember(go, tmDojo, index, teamCats, isDontShowAni, showEmotionBonus)
    if isNull( go) or not tmDojo then
        return
    end
    local scr = CfUtils.GetLuaScr(go, UIFightTeamTeamNode)
    local teamType = self:GetSelectedTeamType()
    local teamIndex = self:GetSelectedTeamIndex()
    if scr then
        --该位置是否被限制上阵
        local isLimitPos = (index > teamType)
        scr:FillLimitStatus(isLimitPos)

        table.insert(self._allTeamPosInfoGo, {
            memberPos = index,
            go = go,
            pos = go.transform.localPosition,
            isLimitPos = isLimitPos or (checkNumber(tmDojo.refId) == 0)
        })

        if not isLimitPos then
            local cardData = self:GetCardData(tmDojo)
            scr:Refresh(cardData, function()
                self:SaveUIState()
                UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {activityUuid = self._activityUuid, upBuffData = self._upBuffData, teamIndex = teamIndex, teamType = self:GetSelectedTeamType()}}, {
                    { id = Constants.UITypeIds.FightTeamPresetDialog}
                })
            end, function()
                --还有多余的牌
                if self:IsEnterTeamCardChoose() then
                    self:SaveUIState()
                    UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {activityUuid = self._activityUuid, upBuffData = self._upBuffData, teamIndex = teamIndex, teamType = self:GetSelectedTeamType()}}, {
                        { id = Constants.UITypeIds.FightTeamPresetDialog}
                    })
                else
                    GameUtils.Toast(localize("武装不足"))
                end
            end, index, self.curLevelId, self.teamTab)

            --羁绊
            scr:FillFettersInfo(tmDojo, function()
                if checkNumber(tmDojo.cardId) <= 0 then
                    GameUtils.Toast(localize("需要先上阵卡牌"))
                    return
                end
                self:SaveUIState()
                UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {targetCardId = tmDojo.cardId, chooseCardStatu = Constants.ChooseCardStatus.Fetter, levelId = nil, activityUuid = self._activityUuid, upBuffData = self._upBuffData, teamIndex = self:GetSelectedTeamIndex(), teamType = self:GetSelectedTeamType()}}, {
                    { id = Constants.UITypeIds.FightTeamPresetDialog}
                })
            end, isDontShowAni)
            
            if self._upBuffData then
                scr:FillUpBuffInfo(self._upBuffData)
            end

            if cardData then
                local synergiesId, synergiesDojo
                if checkNumber(tmDojo.fettersId) > 0 then
                    local dojo = CardComponent:GetCardById(tmDojo.fettersId)
                    synergiesDojo = dojo
                    synergiesId = CardConfMgr:GetInstance():GetRoleCardSynergiesId(cardData.cardId, dojo.cardId)
                end
                self._power = self._power + FormulaUtils.GetCardFightingStrengthen(cardData,
                        {
                            synergiesId = synergiesId,
                            synergiesDojo = synergiesDojo,
                            teamCats = teamCats,
                        },
                        false)
                
            end

            -- 情绪共鸣
            scr:SetEmotionBonusLoopFX(showEmotionBonus)
            if showEmotionBonus and (not isDontShowAni) then
                scr:ShowEmotionBonusFlyFX(self.FightTeamBonusNode.gameObject)
            else
                scr:CloseEmotionBonusFlyFX()
            end
        end
    end
end

--刷新猫球光环技
function FightTeamPresetDialog:RefreshCatBallSkillInfo()
    local isShowCat = self._isShowCatBall and self._isUnlockCatBall
    CfUtils.SetActive(self.SkillInfo.gameObject, isShowCat)
    if not isShowCat then return end

    ---@type UIFightChooseCatBallSkillNode
    local env = self:GetSkillInfoEnv()
    if isNull(env) then return end

    env:FreshUI(self:GetSelectedTeamType(), self:GetSelectedTeamIndex(), function() 
        self:SaveUIState()
    end)
end

--是否还有足够的队员上阵
function FightTeamPresetDialog:IsEnterTeamCardChoose()
    local cards = self:GetAllCardsData()
    if not cards then
        return false
    end

    for i, v in ipairs(cards) do
        if not TeamComponent:IsCardInTeamByTeamType(self:GetSelectedTeamType(), v.id, self:GetSelectedTeamIndex()) then
            return true
        end
    end
    return false
end

--根据当前的关卡类型获取所有的卡牌信息
function FightTeamPresetDialog:GetAllCardsData()
    local t = {}
    local cards = {}
    
    t = CardComponent:GetAllCardTable()
    cards = t

    return cards
end

---刷新战斗力
function FightTeamPresetDialog:RefreshFightPower()
    CfUtils.FillText(self.FightPower, self._power)
end

---保存UI状态
function FightTeamPresetDialog:SaveUIState()
    if not self.controller.Argument.parameters then
        local arguments = CS.Engine.UI.UIArgument()
        arguments = {
            id = self.controller.Argument.id,
            path = self.controller.Argument.path,
            status = self.controller.Argument.status,
            isBackable = self.controller.Argument.isBackable,
            extra = self.controller.Argument.extra,
            hasExcluded = self.controller.Argument.hasExcluded,
            parameters = {}
        }
        self.controller.Argument = arguments
    end
    
    local parameters = self.controller.Argument.parameters or {}
    parameters.teamTypeIndex = self._teamTypeIndex
    self.controller.Argument.parameters = parameters
end
