function FightTeamPresetDialog:GetSelectedTeamIndex()
    return TeamComponent:GetSelectedTeamIndexByTeamType(self:GetSelectedTeamType())
end

--队伍队员数据转卡牌数据
function FightTeamPresetDialog:GetCardData(tmDojo)
    if not tmDojo then
        return nil, false
    end

    local cardData
    local type = checkNumber(tmDojo.type)
    if type == Constants.TeamMemberType.None then
        return nil
    elseif type == Constants.TeamMemberType.PlayerCard then
        cardData = CardComponent:GetCardById(tmDojo.refId)
    end
    return cardData
end

---获取猫球技能env
---@return UIFightChooseCatBallSkillNode
function FightTeamPresetDialog:GetSkillInfoEnv()
    if isNull(self._skillInfoEnv) then
        self._skillInfoEnv = CfUtils.GetLuaScr(self.SkillInfo, "Game.UI.FightTeam.TeamPreset.FightTeamPresetCatBallSkillNode")
    end
    return self._skillInfoEnv
end
--endregion get / set

function FightTeamPresetDialog:ClearEmotionBonusFlyFX()
    local teamType = self:GetSelectedTeamType()
    local count = teamType
    for i = 1, count do
        local teamGo = self["TeamNode"..i]
        if isNotNull(teamGo) then
            local scr = CfUtils.GetLuaScr(teamGo, UIFightTeamTeamNode)
            if isNotNull(scr) then
                scr:CloseEmotionBonusFlyFX()
            end
        end
    end
end

return FightTeamPresetDialog